/**
 * Dynamic Themes theme engine
 * id: mosaic-steel-lights-engine
 * kind: mosaic
 */
(function (global) {
  const enginesApi = global.BGThemeEngines;
  if (!enginesApi || typeof enginesApi.define !== "function") {
    throw new Error("BGThemeEngines is not loaded before mosaic-steel-lights-engine.js");
  }

  const FRAME_URI = 'url("data:image/webp;base64,")';
  const ASPECT_HERO = 3 / 4;
  const COUNT = 16;
  let persistedSide = "right";
  let persistedAt = 0;

  function uniqueUrls(pool) {
    const out = [];
    const seen = new Set();
    (pool || []).forEach(function (src) {
      if (!src || seen.has(src)) return;
      seen.add(src);
      out.push(src);
    });
    return out;
  }

  function isPortrait(root) {
    return !!(root && root.classList && root.classList.contains("dyn-portrait"));
  }

  function rand(a, b) {
    return a + Math.random() * (b - a);
  }

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      const t = arr[i];
      arr[i] = arr[j];
      arr[j] = t;
    }
    return arr;
  }

  function ensureWrap(card) {
    if (card.querySelector(".plate")) return;
    const spin = document.createElement("div");
    spin.className = "spin";
    const drift = document.createElement("div");
    drift.className = "drift";
    const plate = document.createElement("div");
    plate.className = "plate";
    const steel = document.createElement("div");
    steel.className = "steel";
    const shine = document.createElement("div");
    shine.className = "shine";
    while (card.firstChild) plate.appendChild(card.firstChild);
    plate.appendChild(steel);
    plate.appendChild(shine);
    drift.appendChild(plate);
    spin.appendChild(drift);
    card.appendChild(spin);
  }

  function applyCard(card, stage, x, y, w, h, isHero) {
    const W = stage.clientWidth;
    const H = stage.clientHeight;
    card.style.left = ((x / W) * 100).toFixed(3) + "%";
    card.style.top = ((y / H) * 100).toFixed(3) + "%";
    card.style.width = ((w / W) * 100).toFixed(3) + "%";
    card.style.height = ((h / H) * 100).toFixed(3) + "%";
    card.classList.toggle("is-hero", !!isHero);
    card.style.zIndex = isHero ? "12" : "3";
  }

  function packRegion(cards, stage, region, gap) {
    if (!cards.length || region.w < 28 || region.h < 28) return;
    const cols = region.w > stage.clientWidth * 0.4 ? 3 : region.w > stage.clientWidth * 0.22 ? 2 : 1;
    const colW = (region.w - gap * (cols - 1)) / cols;
    const buckets = Array.from({ length: cols }, function () { return []; });
    shuffle(cards.slice()).forEach(function (card, i) {
      buckets[i % cols].push(card);
    });
    buckets.forEach(function (bucket, ci) {
      if (!bucket.length) return;
      const x0 = region.x + ci * (colW + gap);
      let y = region.y + (ci % 2 ? rand(-region.h * 0.02, region.h * 0.05) : rand(-region.h * 0.04, region.h * 0.02));
      bucket.forEach(function (card) {
        const aspect = Math.random() < 0.72 ? rand(1.38, 1.64) : rand(1.04, 1.24);
        const w = colW * rand(0.7, 0.92);
        const h = w / aspect;
        const jx = rand(0, Math.max(0, colW - w));
        applyCard(card, stage, x0 + jx, y, w, h, false);
        y += h + gap + rand(-2, 6);
      });
    });
  }

  function flipSide(root) {
    const now = Date.now();
    if (now - persistedAt < 900) {
      if (root && root.dataset) root.dataset.slSide = persistedSide;
      return persistedSide;
    }
    persistedSide = persistedSide === "left" ? "right" : "left";
    persistedAt = now;
    if (root && root.dataset) {
      root.dataset.slSide = persistedSide;
      root.dataset.slFlipAt = String(now);
    }
    return persistedSide;
  }

  function nextEnter(root) {
    const dir = Math.random() < 0.5 ? "left" : "top";
    if (root && root.dataset) root.dataset.slEnter = dir;
    return dir;
  }

  function layout(state) {
    const stage = state.stage;
    if (!stage || !stage.clientWidth) return;
    const W = stage.clientWidth;
    const H = stage.clientHeight;
    const portrait = isPortrait(state.root);
    const grow = state.heroGrow || 1;
    let heroW = portrait ? W * 0.66 * grow : W * 0.4 * grow;
    let heroH = heroW / ASPECT_HERO;
    const maxH = H * (portrait ? 0.5 : 0.9);
    if (heroH > maxH) {
      heroH = maxH;
      heroW = heroH * ASPECT_HERO;
    }
    const side = state.heroSide === "right" ? "right" : "left";
    const inset = portrait ? W * 0.035 : W * 0.028;
    const heroX = side === "right" ? W - heroW - inset : inset;
    const heroY = portrait ? H * 0.04 : H * 0.028;
    const hero = state.cards[state.heroIndex];
    applyCard(hero, stage, heroX, heroY, heroW, heroH, true);

    const sats = [];
    state.cards.forEach(function (card, i) {
      if (i !== state.heroIndex) sats.push(card);
    });
    const gap = Math.max(8, W * 0.01);
    const pad = 0;
    const under = {
      x: heroX,
      y: heroY + heroH + gap,
      w: heroW,
      h: Math.max(0, H - (heroY + heroH + gap) + H * 0.08)
    };
    const open = side === "right"
      ? { x: 0, y: -H * 0.02, w: Math.max(40, heroX - gap), h: H * 1.12 }
      : { x: heroX + heroW + gap, y: -H * 0.02, w: Math.max(40, W - heroX - heroW - gap), h: H * 1.12 };
    const underN = under.h > H * 0.12 ? 1 : 0;
    const underCards = sats.splice(0, underN);
    packRegion(underCards, stage, under, gap);
    packRegion(sats, stage, open, gap);
  }

  function enterFrom(cards, dir) {
    const off = dir === "top" ? "translate3d(0,-118%,0)" : "translate3d(-118%,0,0)";
    cards.forEach(function (card, i) {
      const spin = card.querySelector(".spin") || card;
      const delay = (0.03 + i * 0.045).toFixed(3);
      spin.style.transition = "none";
      spin.style.transform = off + " rotate(var(--tilt, -2deg))";
      void spin.offsetWidth;
      spin.style.transition = "transform 0.92s " + delay + "s cubic-bezier(0.22, 0.78, 0.2, 1)";
      spin.style.transform = "translate3d(0,0,0) rotate(var(--tilt, -2deg))";
    });
  }

  function ensureFx(bg) {
    if (!bg) return { flashes: null, dust: null };
    let flashes = bg.querySelector(".flashes");
    if (!flashes) {
      flashes = document.createElement("div");
      flashes.className = "flashes";
      flashes.setAttribute("aria-hidden", "true");
      bg.appendChild(flashes);
    }
    let dust = bg.querySelector(".dust");
    if (!dust) {
      dust = document.createElement("div");
      dust.className = "dust";
      dust.setAttribute("aria-hidden", "true");
      bg.appendChild(dust);
    }
    return { flashes: flashes, dust: dust };
  }

  function seedDust(host) {
    if (!host) return;
    while (host.childElementCount < 130) {
      const p = document.createElement("i");
      p.style.left = rand(0, 100).toFixed(2) + "%";
      p.style.top = rand(0, 100).toFixed(2) + "%";
      p.style.setProperty("--dx", rand(-26, 26).toFixed(2) + "cqw");
      p.style.setProperty("--dy", rand(-22, 22).toFixed(2) + "cqh");
      p.style.setProperty("--dust-s", rand(0.45, 1.85).toFixed(2));
      p.style.setProperty("--dust-t", rand(9, 22).toFixed(1) + "s");
      p.style.setProperty("--dust-d", (-rand(0, 20)).toFixed(1) + "s");
      host.appendChild(p);
    }
  }

  function startFlashes(state, host) {
    if (!host) return;
    while (host.childElementCount < 18) host.appendChild(document.createElement("i"));
    state.fxOn = true;
    function pop() {
      if (!state.fxOn || !host.isConnected) return;
      const nodes = host.children;
      const burst = 2 + (Math.random() < 0.55 ? 1 : 0) + (Math.random() < 0.28 ? 1 : 0);
      for (let k = 0; k < burst; k += 1) {
        const el = nodes[Math.floor(Math.random() * nodes.length)];
        el.style.left = rand(4, 96).toFixed(1) + "%";
        el.style.top = rand(6, 92).toFixed(1) + "%";
        el.style.setProperty("--flash-s", rand(0.4, 2.05).toFixed(2));
        el.classList.remove("on");
        void el.offsetWidth;
        el.classList.add("on");
      }
      state.flashTimer = window.setTimeout(pop, rand(90, 620));
    }
    state.flashTimer = window.setTimeout(pop, rand(80, 280));
  }

  function applyBgTint(themeRoot, settings) {
    if (!themeRoot || !themeRoot.style) return;
    const hex = settings && (settings.bgTint || settings.ribbon || settings.Ribbon);
    if (hex) themeRoot.style.setProperty("--bg-tint", hex);
  }

  function refreshPhotos(state, hostApi, pool) {
    const api = hostApi || state.api;
    state.cards.forEach(function (card, i) {
      if (i === state.heroIndex) return;
      const img = card.querySelector("img");
      const src =
        api && typeof api.nextUrl === "function"
          ? api.nextUrl(img && img.src)
          : (pool && pool[Math.floor(Math.random() * pool.length)]) || "";
      if (img && src && (img.currentSrc || img.src) !== src) img.src = src;
    });
  }

  enginesApi.define({
    id: "mosaic-steel-lights-engine",
    kind: "mosaic",
    interval: 4200,

    mount(themeRoot, pool, hostApi, settings) {
      const mosaicApi = global.BGMosaicThemes || {};
      const makeCard =
        mosaicApi.makeCard ||
        function (src) {
          const card = document.createElement("div");
          card.className = "dyn-card";
          const img = document.createElement("img");
          img.alt = "";
          img.src = src || "";
          card.appendChild(img);
          return card;
        };

      let shell = themeRoot.querySelector(".sl");
      if (!shell) {
        themeRoot.innerHTML =
          '<div class="sl"><div class="bg"><div class="sky"><div class="sky-tint"></div></div><div class="flashes" aria-hidden="true"></div><div class="haze"></div><div class="dust" aria-hidden="true"></div></div><div class="stage"></div><div class="logo-slot" data-logo></div><div class="qr-slot" data-qr></div></div>';
        shell = themeRoot.querySelector(".sl");
      }
      if (!shell.querySelector(".sky-tint")) {
        const sky = shell.querySelector(".sky") || shell.querySelector(".bg");
        if (sky) {
          const tint = document.createElement("div");
          tint.className = "sky-tint";
          sky.appendChild(tint);
        }
      }
      const leftover = shell.querySelector(".ribbon");
      if (leftover) leftover.remove();
      themeRoot.style.setProperty("--steel-frame", FRAME_URI);
      applyBgTint(themeRoot, settings);
      const fx = ensureFx(shell.querySelector(".bg"));
      seedDust(fx.dust);
      const stage = shell.querySelector(".stage");
      const urls = uniqueUrls(pool);
      const cards = [];
      for (let i = 0; i < COUNT; i += 1) {
        const src = urls.length ? urls[i % urls.length] : "";
        const card = makeCard(src);
        card.style.position = "absolute";
        card.style.margin = "0";
        ensureWrap(card);
        stage.appendChild(card);
        cards.push(card);
      }

      const state = {
        root: themeRoot,
        stage: stage,
        cards: cards,
        api: hostApi,
        heroIndex: 0,
        heroSide: flipSide(themeRoot),
        heroGrow: rand(0.96, 1.06),
        busy: false,
        ro: null,
        fxOn: false,
        flashTimer: 0
      };
      startFlashes(state, fx.flashes);
      layout(state);
      enterFrom(cards, nextEnter(themeRoot));
      if (typeof ResizeObserver !== "undefined") {
        state.ro = new ResizeObserver(function () {
          if (state.busy) return;
          layout(state);
        });
        state.ro.observe(stage);
      }
      return state;
    },

    applySettings(themeRoot, _state, settings) {
      applyBgTint(themeRoot, settings);
    },

    tick(_themeRoot, pool, state, hostApi) {
      if (!state || !state.cards || state.cards.length < 2 || state.busy) return;
      const n = state.cards.length;
      let next = state.heroIndex;
      while (next === state.heroIndex) next = Math.floor(Math.random() * n);
      state.heroIndex = next;
      state.heroSide = flipSide(state.root);
      state.heroGrow = rand(0.94, 1.08);
      const dir = nextEnter(state.root);
      refreshPhotos(state, hostApi, pool);
      layout(state);
      state.busy = true;
      enterFrom(state.cards, dir);
      window.setTimeout(function () {
        state.busy = false;
        state.cards.forEach(function (card) {
          const spin = card.querySelector(".spin") || card;
          spin.style.transition = "";
          spin.style.transform = "";
          card.style.transition = "";
          card.style.transform = "";
        });
      }, 1400);
    },

    unmount(themeRoot, state) {
      if (state) {
        state.fxOn = false;
        if (state.flashTimer) {
          window.clearTimeout(state.flashTimer);
          state.flashTimer = 0;
        }
        if (state.ro) {
          try {
            state.ro.disconnect();
          } catch (err) {}
          state.ro = null;
        }
      }
      if (themeRoot) themeRoot.replaceChildren();
    }
  });
})(typeof globalThis !== "undefined" ? globalThis : window);
